import csv

def load_expenses(path):
    with open(path, newline="") as f:
        return [{**row, "amount": float(row["amount"])} for row in csv.DictReader(f)]


def total_by_category(expenses):
    totals = {}
    for e in expenses:
        totals[e["category"]] = round(totals.get(e["category"], 0) + e["amount"], 2)
    return totals


def write_report(expenses, path):
    totals = total_by_category(expenses)
    lines = [f"{cat}: {amount:.2f}" for cat, amount in sorted(totals.items(), key=lambda kv: kv[1], reverse=True)]
    lines.append(f"TOTAL: {sum(totals.values()):.2f}")
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")

